#!/usr/bin/env python
"""Duck-typed interfaces for modular components."""


class SearchStrategy(object):
    """Interface for building search URLs."""
    def build_search_url(self, keywords, args):
        """Build search URL from keywords and arguments."""
        raise NotImplementedError


class Downloader(object):
    """Interface for fetching and parsing pages."""
    def download_page(self, url):
        """Download raw HTML content from a URL."""
        raise NotImplementedError

    def download_extended_page(self, url, chromedriver):
        """Download extended page with pagination (e.g., via Selenium)."""
        raise NotImplementedError

    def get_all_tabs(self, page, keywords):
        """Extract related search tabs from page HTML."""
        raise NotImplementedError

    def get_all_items(self, page, args):
        """Extract image items (URLs, metadata) from page HTML."""
        raise NotImplementedError


class Saver(object):
    """Interface for saving downloaded images and metadata."""
    def create_directory(self, path):
        """Create directory if it doesn't exist."""
        raise NotImplementedError

    def download_image(self, image_url, filename, timeout, args):
        """Download image to specified filename."""
        raise NotImplementedError

    def save_source(self, path, source_url, filename):
        """Append source info to source list file."""
        raise NotImplementedError
